/**
 * Bundles the in-WebView reader (src/services/epub/injected/main.ts) into a single IIFE and
 * writes it as a string constant the app injects into each spine document.
 *
 *   node scripts/build-reader-bundle.mjs          # one-off build
 *   node scripts/build-reader-bundle.mjs --watch  # rebuild on change (pair with `expo start`)
 *
 * Output is generated (gitignored): src/services/epub/injected/generated/readerBundle.ts
 */
import { build, context } from "esbuild";
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const entry = path.join(root, "src/services/epub/injected/main.ts");
const outFile = path.join(root, "src/services/epub/injected/generated/readerBundle.ts");

const options = {
  entryPoints: [entry],
  bundle: true,
  platform: "browser",
  format: "iife",
  // Android System WebView / WKWebView on the oldest devices we support.
  target: ["es2019"],
  minify: true,
  legalComments: "none",
  write: false,
  logLevel: "warning",
};

async function emit(result) {
  const js = result.outputFiles?.[0]?.text;
  if (!js) {
    throw new Error("esbuild produced no output");
  }
  const contents = [
    "// Generated by scripts/build-reader-bundle.mjs — do not edit.",
    `export const READER_BUNDLE = ${JSON.stringify(js)};`,
    "",
  ].join("\n");
  await mkdir(path.dirname(outFile), { recursive: true });
  await writeFile(outFile, contents, "utf8");
  console.log(`reader bundle: ${(js.length / 1024).toFixed(1)} KiB → ${path.relative(root, outFile)}`);
}

if (process.argv.includes("--watch")) {
  const ctx = await context({
    ...options,
    plugins: [
      {
        name: "emit-reader-bundle",
        setup(b) {
          b.onEnd((result) => {
            if (result.errors.length === 0) {
              emit(result).catch((error) => console.error(error));
            }
          });
        },
      },
    ],
  });
  await ctx.watch();
  console.log("watching reader bundle sources…");
} else {
  await emit(await build(options));
}
